import java.nio.file.Files;
import java.nio.file.Paths;

public class App {
    public static void main(String[] args) {
        Pulumi.run(App::stack);
    }

    public static void stack(Context ctx) {
        var my_import_bucket = new Bucket("my-import-bucket", BucketArgs.builder()
            .name("snapshot-bucket-to-import")
            .build());

        var qcow_object = new Item("qcow-object", ItemArgs.builder()
            .bucket(snapshot_bucket.name())
            .key("export/my-snapshot.qcow2")
            .build());

        var toExport = new Volume("toExport", VolumeArgs.builder()
            .iops(5000)
            .name("to-export")
            .export(Arrays.asList(Map.ofEntries(
                Map.entry("bucket", "snapshot-bucket-to-import"),
                Map.entry("key", "exports/my-snapshot.qcow2")
            )))
            .build());

    }
}
