const kubernetesClusterWorkers1 = new scaleway.kubernetes.Pool("kubernetes_cluster_workers_1", {
    clusterId: kubernetesCluster.id,
    name: `${kubernetesClusterId}_${nodeType}_1`,
    nodeType: nodeType,
    autoscaling: true,
    autohealing: true,
    size: 5,
    minSize: 5,
    maxSize: 10,
    waitForPoolReady: true,
});
