const vpc02 = new scaleway.network.Vpc("vpc02", {name: "my-vpc-target"});
const main = new scaleway.network.Connector("main", {
    name: "my-vpc-connector",
    vpcId: vpc01.id,
    targetVpcId: vpc02.id,
});
